import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"Is Clash compatible with Surge?","description":"How to move Surge subscriptions, Snell, Shadowsocks, Trojan, WireGuard nodes and routing policies to Clash for iOS.","frontmatter":{"title":"Is Clash compatible with Surge?","description":"How to move Surge subscriptions, Snell, Shadowsocks, Trojan, WireGuard nodes and routing policies to Clash for iOS.","head":[["meta",{"name":"keywords","content":"Surge to Clash,Surge iOS,Surge profile,Snell iOS,Surge subscription,Clash iOS"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"FAQPage\\",\\"mainEntity\\":[{\\"@type\\":\\"Question\\",\\"name\\":\\"How do I move a Surge profile to Clash?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Organize nodes and routing policies as mihomo YAML, or add a Clash / mihomo subscription from the provider. Recreate modules, scripts and rewrites with the corresponding Clash rules and features.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Does Clash support Surge Snell nodes?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Yes. Add a Snell node through mihomo YAML, a compatible subscription or the node editor.\\"}}]}"]]},"headers":[],"relativePath":"guide/compatibility/surge.md","filePath":"guide/compatibility/surge.md","lastUpdated":1785318168000}`),a={name:`guide/compatibility/surge.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="is-clash-compatible-with-surge" tabindex="-1">Is Clash compatible with Surge? <a class="header-anchor" href="#is-clash-compatible-with-surge" aria-label="Permalink to “Is Clash compatible with Surge?”">​</a></h1><p><strong>Shared node protocols continue to work, while routing policies can be organized as mihomo YAML.</strong></p><p><a href="https://manual.nssurge.com/overview/quick-start.html" target="_blank" rel="noreferrer">Surge uses its own profile format</a>, with sections such as <code>[General]</code>, <code>[Proxy]</code>, <code>[Proxy Group]</code> and <code>[Rule]</code>. For migration, organize nodes and policy groups as mihomo YAML, then use Clash rules and matching features to recreate the routing experience.</p><h2 id="which-surge-nodes-can-be-reused" tabindex="-1">Which Surge nodes can be reused? <a class="header-anchor" href="#which-surge-nodes-can-be-reused" aria-label="Permalink to “Which Surge nodes can be reused?”">​</a></h2><p>Clash supports Snell and multiple protocols shared by both products, including:</p><ul><li>HTTP and SOCKS;</li><li>Shadowsocks;</li><li>VMess and Trojan;</li><li>WireGuard;</li><li>Snell.</li></ul><p>Snell is normally added through mihomo YAML, a compatible subscription that returns mihomo YAML, or the node editor. Other nodes can be recreated from their server and protocol parameters.</p><h2 id="how-to-migrate" tabindex="-1">How to migrate <a class="header-anchor" href="#how-to-migrate" aria-label="Permalink to “How to migrate”">​</a></h2><ol><li>Prefer a mihomo / Clash subscription from the provider.</li><li>If only a Surge profile is available, recreate the required nodes from their parameters.</li><li>Rewrite Surge policy groups and rules as mihomo YAML.</li><li>Use Clash rules and matching features to recreate the needs expressed by modules, scripts and rewrites.</li></ol><h2 id="what-to-configure-during-migration" tabindex="-1">What to configure during migration <a class="header-anchor" href="#what-to-configure-during-migration" aria-label="Permalink to “What to configure during migration”">​</a></h2><ul><li>organize Surge nodes and policies as mihomo YAML;</li><li>express the original routing logic with Clash rules;</li><li>recreate module, rewrite, MITM and script needs with matching Clash features;</li><li>set app preferences to match your workflow.</li></ul><p>The same server can be used directly once its protocol and parameters match.</p><p>Return to the <a href="/clash.md/guide/compatibility">compatibility overview</a>.</p>`,13)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};